import assert from 'node:assert/strict';
import { readFile, writeFile } from 'node:fs/promises';
import pLimit from 'p-limit';

const { concurrency, values } = JSON.parse(await readFile(process.env.EVALUATION_INPUT, 'utf8'));
const limit = pLimit(concurrency);
let active = 0;
let peak = 0;
const observations = {};
try {
  const actual = await Promise.all(values.map((value) => limit(async () => {
    active += 1;
    peak = Math.max(peak, active);
    await new Promise((resolve) => setTimeout(resolve, 15 + (value % 3) * 5));
    active -= 1;
    return value * 2;
  })));
  observations.overlap = { concurrency, peak, active_after: active, input: values, actual, expected: values.map((value) => value * 2) };
  assert.equal(peak, concurrency);
  assert.equal(active, 0);
  assert.deepEqual(actual, observations.overlap.expected);
  assert.equal(limit.activeCount, 0);
  assert.equal(limit.pendingCount, 0);
  let propagated = false;
  await assert.rejects(limit(async () => { throw new Error('expected rejection'); }), (error) => {
    propagated = error.message === 'expected rejection';
    return propagated;
  });
  observations.rejection_propagated = propagated;
  const recovery = await limit(async () => 'still works');
  observations.recovery = recovery;
  assert.equal(recovery, 'still works');
} finally {
  await writeFile(process.env.EVALUATION_RESULTS, JSON.stringify(observations, null, 2));
}
